PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT REFERENCES users(id),org_id TEXT REFERENCES organizations(id),role TEXT NOT NULL CHECK(role IN ('owner','staff')),PRIMARY KEY(user_id,org_id));
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),title TEXT NOT NULL,description TEXT NOT NULL,reward TEXT NOT NULL,terms TEXT NOT NULL,venue TEXT NOT NULL,starts INTEGER NOT NULL,ends INTEGER NOT NULL,voucher_days INTEGER NOT NULL CHECK(voucher_days BETWEEN 1 AND 365),target INTEGER NOT NULL CHECK(target>0),capacity INTEGER NOT NULL CHECK(capacity>0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused')),paid INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS stops(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),name TEXT NOT NULL,lat REAL NOT NULL,lon REAL NOT NULL,radius INTEGER NOT NULL CHECK(radius BETWEEN 10 AND 100));
CREATE TABLE IF NOT EXISTS hunts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),campaign_id TEXT NOT NULL REFERENCES campaigns(id),expires INTEGER NOT NULL,completed INTEGER,UNIQUE(user_id,campaign_id));
CREATE TABLE IF NOT EXISTS collections(hunt_id TEXT REFERENCES hunts(id),stop_id TEXT REFERENCES stops(id),created INTEGER NOT NULL,PRIMARY KEY(hunt_id,stop_id));
CREATE TABLE IF NOT EXISTS vouchers(id TEXT PRIMARY KEY,hunt_id TEXT UNIQUE NOT NULL REFERENCES hunts(id),code TEXT UNIQUE NOT NULL,expires INTEGER NOT NULL,redeemed INTEGER,redeemed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT,action TEXT NOT NULL,entity TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_hunts_campaign ON hunts(campaign_id,expires);
CREATE INDEX IF NOT EXISTS ix_campaigns_org ON campaigns(org_id);
